const downloadTransferFallbackExtras: TranslationMap = {
  'download.uploadComplete': 'Upload complete',
  'download.downloading': 'Downloading',
  'download.uploading': 'Uploading',
  'download.failed': 'Transfer failed',
  'download.uploadFailed': 'Upload failed',
  'download.stalled': 'Transfer stalled. Check the connection and retry.',
  'download.canceled': 'Upload canceled',
  'download.cancel': 'Cancel',
  'download.remoteDisabled': 'Remote ISO download is disabled in Settings > Appearance.',
  'download.remoteFailed': 'Remote ISO download failed'
};

function downloadTransferTranslation(
  uploadComplete: string,
  downloading: string,
  uploading: string,
  failed: string,
  uploadFailed: string,
  stalled: string,
  canceled: string,
  cancel: string,
  remoteDisabled: string,
  remoteFailed: string
): TranslationMap {
  return {
    'download.uploadComplete': uploadComplete,
    'download.downloading': downloading,
    'download.uploading': uploading,
    'download.failed': failed,
    'download.uploadFailed': uploadFailed,
    'download.stalled': stalled,
    'download.canceled': canceled,
    'download.cancel': cancel,
    'download.remoteDisabled': remoteDisabled,
    'download.remoteFailed': remoteFailed
  };
}

