const virtualMediaFallbackExtras: TranslationMap = {
  'image.usbReconnect': 'USB reconnect',
  'image.usbReconnectConfirm':
    'Reconnect the USB gadget only if the remote host did not notice the media change. Keyboard and mouse may briefly disconnect.',
  'image.usbReconnectSuccess': 'USB reconnected',
  'image.usbReconnectFailed': 'USB reconnect failed'
};

function virtualMediaTranslation(
  reconnect: string,
  confirm: string,
  success: string,
  failed: string
): TranslationMap {
  return {
    'image.usbReconnect': reconnect,
    'image.usbReconnectConfirm': confirm,
    'image.usbReconnectSuccess': success,
    'image.usbReconnectFailed': failed
  };
}

